require "rails_helper"

RSpec.describe "Timekeeping internal handoff routes, refused callers" do
  # "Every handoff endpoint refuses a caller without service credentials"
  it "refuses every handoff route without service credentials and changes nothing" do
    service_token = "service-#{SecureRandom.hex(24)}"
    routes = [
      [:get, "/internal/v1/handoff/checkpoint", nil],
      [:put, "/internal/v1/handoff/checkpoint", "{}"],
      [:post, "/internal/v1/handoff/entry_id_sequence", { above: 500 }.to_json],
      [:get, "/internal/v1/handoff/outbox_position", nil],
      [:put, "/internal/v1/handoff/correction_snapshots", { generation: 2, version: 1, snapshots: [] }.to_json],
      [:post, "/internal/v1/handoff/admission/fence", nil],
      [:post, "/internal/v1/handoff/admission/admit", { generation: 7 }.to_json]
    ]
    callers = [
      nil,
      "Bearer #{service_token}x",
      "Bearer #{mint_token({ sub: 7, company_id: 1, role: 'owner' })}",
      "Bearer #{mint_token({ sub: 7, company_id: 1, role: 'admin' })}"
    ]

    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      Timekeeping::Admission.ensure_initial!
      Timekeeping::Admission.admit!(generation: 1)
      before_state = [Entry.count, OutboxSnapshot.count, AuditEvent.count, IdempotencyReceipt.count,
                      Timekeeping::Admission.current.generation]

      answers = routes.flat_map do |verb, path, body|
        callers.map do |authorization|
          headers = { "Content-Type" => "application/json" }
          headers["Authorization"] = authorization if authorization
          public_send(verb, path, params: body, headers:)
          [path, verb, response.status, response.parsed_body]
        end
      end

      expect(answers).to all(satisfy { |answer| answer[2] == 401 && answer[3] == { "reason" => "unauthorized" } })
      expect([Entry.count, OutboxSnapshot.count, AuditEvent.count, IdempotencyReceipt.count,
              Timekeeping::Admission.current.generation]).to eq(before_state)
    end
  end
end

